-- IP-006 Long-held account sends a large sum to an account in the same name opened days ago
SELECT 'IP-006' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
WHERE (a.direction = 'out' AND a.channel IN ('rtp', 'fednow', 'p2p', 'wire', 'ach', 'internal') AND a.payee_self = 1 AND a.amount_cents >= 1000000 AND a.ts >= (a.account_opened_ts + 63072000) AND a.ts < (a.counterparty_opened_ts + 1209600));
